mapper.select:
SELECT id, category_id AS categoryId, title, description, cover_storage_key AS coverStorageKey, demo_result_key AS demoResultKey, required_image_count AS requiredImageCount, accepted_mime_types AS acceptedMimeTypes, max_file_size_bytes AS maxFileSizeBytes, active, sort_order AS sortOrder, created_at AS createdAt FROM template WHERE active = TRUE
AND category_id = #{categoryId}
ORDER BY sort_order ASC, id ASC
